  );

  struct gkyl_msgpack_map_elem desc_nu_cross[] = {{
    .key = "Description",
    .elem_type = GKYL_MP_STRING,
    .cval =
      "Cross-species drift velocity and thermal speed squared, or cross-species collision frequency.",
